SourceCode.Declaration:
/// <summary>
/// Data contract for the custom scheduled batch posting of recurring free text invoices.
/// Exposes a query (backed by <c>METCustRecurrenceInvoiceBatchPost</c>) that allows the user
/// to filter <c>CustRecurrenceInvoiceGroup</c> records by generation date and invoice date
/// via the "Records to include" filter in the batch dialog.
/// When the batch runs it will find all <c>CustRecurrenceInvoiceGroup</c> records that match
/// the query and have a Posted status of No, and post them.
/// </summary>
[DataContractAttribute, SysOperationAlwaysInitializeAttribute]
class METCustRecurrenceInvoiceBatchPostContract
{
    str packedQuery;

}

Method.Source:
/// <summary>
/// Gets or sets the packed query used to filter recurring invoice groups.
/// The query is surfaced in the batch dialog as "Records to include" and allows
/// filtering by generation date (<c>RecurrenceInvoice.RecurrenceInvoiceDate</c>)
/// and invoice date (<c>CustInvoiceTable.InvoiceDate</c>).
/// </summary>
[
        DataMemberAttribute,
        AifQueryTypeAttribute('_packedQuery', queryStr(METCustRecurrenceInvoiceBatchPost))
    ]
    public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Unpacks and returns the <c>Query</c> object from the stored packed query string.
/// </summary>
/// <returns>The unpacked <c>Query</c> object.</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Packs and stores the provided <c>Query</c> object.
/// </summary>
/// <param name="_query">The <c>Query</c> object to pack and store.</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// Constructs a new instance of the <c>METCustRecurrenceInvoiceBatchPostContract</c> class.
/// </summary>
/// <returns>A new instance of the <c>METCustRecurrenceInvoiceBatchPostContract</c> class.</returns>
public static METCustRecurrenceInvoiceBatchPostContract construct()
{
    return new METCustRecurrenceInvoiceBatchPostContract();
}
